<?php
$bookingLabels=['pending'=>__('Chờ duyệt'),'confirmed'=>__('Đã xác nhận'),'rejected'=>__('Bị từ chối'),'cancelled'=>__('Đã hủy'),'completed'=>__('Hoàn thành')];
$filters=[''=>__('Tất cả'),'unpaid'=>__('Chưa thanh toán'),'paid'=>__('Đã thanh toán'),'refunded'=>__('Đã hoàn tiền'),'not_required'=>__('Không cần thanh toán')];
?>
<section class="page-section"><div class="container">
<div class="section-title"><div><p class="eyebrow"><?= e(__('VẬN HÀNH')) ?></p><h1><?= e(__('Thanh toán')) ?></h1><p><?= e(__('Khách thanh toán trực tiếp khi nhận phòng. Host hoặc Admin ghi nhận “Đã thu tiền” từ ngày nhận phòng; hoàn tiền cần ghi chú và được lưu nhật ký.')) ?></p></div><a class="btn btn-ghost text-nowrap" href="<?= e(url('/admin')) ?>"><?= e(__('Quay lại quản trị')) ?></a></div>
<div class="stat-grid payment-totals"><div><span><?= e(__('Đã thu')) ?></span><strong><?= e(__('{amount}đ', ['amount'=>number_format((float)($totals['collected_amount']??0),0,',','.')])) ?></strong><small><?= e(__('{count} booking', ['count'=>(int)($totals['paid_count']??0)])) ?></small></div><div><span><?= e(__('Chờ thu (đã xác nhận)')) ?></span><strong><?= e(__('{amount}đ', ['amount'=>number_format((float)($totals['outstanding_amount']??0),0,',','.')])) ?></strong><small><?= e(__('{count} booking', ['count'=>(int)($totals['outstanding_count']??0)])) ?></small></div><div><span><?= e(__('Đã hoàn tiền')) ?></span><strong><?= e(__('{amount}đ', ['amount'=>number_format((float)($totals['refunded_amount']??0),0,',','.')])) ?></strong><small><?= e(__('{count} booking', ['count'=>(int)($totals['refunded_count']??0)])) ?></small></div></div>
<section class="surface-card mt-4"><form class="form-row align-items-end" method="get" action="<?= e(url('/admin/payments')) ?>"><div class="form-group col-md-4"><label for="payment-status"><?= e(__('Trạng thái thanh toán')) ?></label><select class="form-control" id="payment-status" name="status"><?php foreach($filters as $value=>$label): ?><option value="<?= e($value) ?>" <?= $status===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="form-group col-md-5"><label for="payment-search"><?= e(__('Mã booking, tên/email khách hoặc tên chỗ ở')) ?></label><input class="form-control" id="payment-search" name="q" maxlength="254" value="<?= e($query) ?>"></div><div class="form-group col-md-3"><button class="btn btn-outline-primary btn-block" type="submit"><?= e(__('Lọc')) ?></button></div></form>
<?php if(!$payments): ?><div class="empty-state"><h3><?= e(__('Không có booking phù hợp')) ?></h3><p><?= e(__('Thử bỏ bộ lọc hoặc tìm bằng từ khóa khác.')) ?></p><?php if($status!==''||$query!==''): ?><a class="btn btn-primary" href="<?= e(url('/admin/payments')) ?>"><?= e(__('Xóa bộ lọc')) ?></a><?php endif; ?></div><?php else: ?>
<p class="text-muted small"><?= e(__('Hiển thị {count} booking mới nhất', ['count'=>count($payments)])) ?><?= count($payments)>=200?' '.e(__('(tối đa 200; hãy lọc để thu hẹp)')):'' ?>.</p>
<div class="table-responsive" tabindex="0" role="region" aria-label="<?= e(__('Danh sách thanh toán')) ?>"><table class="table payment-table"><thead><tr><th>Booking</th><th><?= e(__('Khách / Host')) ?></th><th><?= e(__('Ngày ở')) ?></th><th><?= e(__('Số tiền')) ?></th><th><?= e(__('Thanh toán')) ?></th><th><?= e(__('Thao tác')) ?></th></tr></thead><tbody>
<?php foreach($payments as $payment): ?><tr><td><a href="<?= e(url('/bookings/'.(int)$payment['booking_id'])) ?>">#<?= (int)$payment['booking_id'] ?></a> · <?= e($payment['title']) ?><br><span class="status status-<?= e($payment['booking_status']) ?>"><?= e($bookingLabels[$payment['booking_status']]??$payment['booking_status']) ?></span><?php if($payment['promotion_code']!==''): ?> <small class="promo-code"><?= e($payment['promotion_code']) ?></small><?php endif; ?></td>
<td><?= e($payment['guest_name']) ?><br><small><?= e($payment['guest_email']) ?></small><br><small>Host: <?= e($payment['host_name']) ?></small></td>
<td><?= e(date('d/m/Y',strtotime($payment['check_in']))) ?> → <?= e(date('d/m/Y',strtotime($payment['check_out']))) ?></td>
<td><?= e(__('{amount}đ', ['amount'=>number_format((float)$payment['amount_due'],0,',','.')])) ?></td>
<td><span class="status status-<?= e($payment['payment_state']) ?>"><?= e(__(\App\Models\BookingExtras::paymentLabel($payment['payment_state']))) ?></span><?php if($payment['paid_at']): ?><br><small><?= e(__('Thu: {time}', ['time'=>display_date($payment['paid_at'],true)])) ?></small><?php endif; ?><?php if($payment['refunded_at']): ?><br><small><?= e(__('Hoàn: {time}', ['time'=>display_date($payment['refunded_at'],true)])) ?></small><?php endif; ?><?php if($payment['payment_note']): ?><br><small class="text-muted"><?= e($payment['payment_note']) ?></small><?php endif; ?></td>
<td><?php if($payment['can_mark_paid']): ?><form method="post" action="<?= e(url('/admin/payments/'.(int)$payment['booking_id'].'/paid')) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-soft" data-confirm="<?= e(__('Xác nhận đã thu {amount}đ của booking #{id}?', ['amount'=>number_format((float)$payment['amount_due'],0,',','.'), 'id'=>(int)$payment['booking_id']])) ?>"><?= e(__('Đã thu tiền')) ?></button></form>
<?php elseif($payment['payment_status']==='paid'): ?><form class="refund-form" method="post" action="<?= e(url('/admin/payments/'.(int)$payment['booking_id'].'/refund')) ?>"><?= csrf_field() ?><label class="sr-only" for="refund-note-<?= (int)$payment['booking_id'] ?>"><?= e(__('Lý do hoàn tiền booking #{id}', ['id'=>(int)$payment['booking_id']])) ?></label><input class="form-control form-control-sm mb-1" id="refund-note-<?= (int)$payment['booking_id'] ?>" name="note" maxlength="500" placeholder="<?= e(__('Lý do hoàn tiền')) ?>" required><button class="btn btn-sm btn-outline-danger" data-confirm="<?= e(__('Ghi nhận đã hoàn tiền booking #{id}? Thao tác được lưu nhật ký.', ['id'=>(int)$payment['booking_id']])) ?>"><?= e(__('Hoàn tiền')) ?></button></form>
<?php elseif($payment['payment_state']==='unpaid' && in_array($payment['booking_status'],['confirmed','completed'],true)): ?><small class="text-muted"><?= e(__('Thu từ ngày nhận phòng')) ?></small><?php else: ?><span class="text-muted">—</span><?php endif; ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?></section>
</div></section>
